export function createContext() {
  return {
    prefix: "island:",
    extra: 17,
    async env(name) {
      return name === "SCRIPTC_TEST_ENV" ? this.prefix + "from-harness" : undefined;
    },
    async fileExists(path) {
      return this.prefix === "island:" && path === "/scriptc-auth-context-present";
    },
  };
}
